import { ethers } from 'ethers'
import { PoolInfo } from '../types/AbstractLpTypes'

/**
 * Service for detecting pool existence and reading pool state
 * Pure functions that can be easily tested in isolation
 */
export class PoolDetectionService {
  private readonly factoryAbi = [
    'function getPool(address tokenA, address tokenB, int24 tickSpacing) view returns (address pool)'
  ]
  
  private readonly poolAbi = [
    // Abstract DEX: 6 parameters (missing 'unlocked')
    'function slot0() view returns (uint160 sqrtPriceX96, int24 tick, uint16 observationIndex, uint16 observationCardinality, uint16 observationCardinalityNext, uint8 feeProtocol)'
  ]

  /**
   * Get complete pool information including existence and current price
   */
  async getPoolInfo(
    token0: string,
    token1: string, 
    tickSpacing: number,
    clFactoryAddress: string,
    provider: any
  ): Promise<PoolInfo> {
    try {
      
      const clFactory = new ethers.Contract(clFactoryAddress, this.factoryAbi, provider)
      const poolAddress = await clFactory.getPool(token0, token1, tickSpacing)
      const exists = poolAddress !== '0x0000000000000000000000000000000000000000'

      let sqrtPriceX96 = '0'
      let tick = 0

      if (exists) {
        try {
          const poolState = await this.readPoolPrice(poolAddress, provider)
          sqrtPriceX96 = poolState.sqrtPriceX96
          tick = poolState.tick
          
        } catch (error) {
          console.warn('Failed to read pool state, using defaults:', error)
          // Keep defaults: sqrtPriceX96 = '0', tick = 0
        }
      }

      const poolInfo: PoolInfo = {
        address: poolAddress,
        exists,
        sqrtPriceX96,
        tick,
        tickSpacing
      }

      return poolInfo

    } catch (error) {
      console.error('Pool detection failed:', error)
      
      // Return safe defaults
      return {
        address: '0x0000000000000000000000000000000000000000',
        exists: false,
        sqrtPriceX96: '0',
        tick: 0,
        tickSpacing
      }
    }
  }

  /**
   * Read current price from an existing pool
   * Isolated function for easier testing
   */
  async readPoolPrice(poolAddress: string, provider: any): Promise<{ sqrtPriceX96: string; tick: number }> {
    try {
      const poolContract = new ethers.Contract(poolAddress, this.poolAbi, provider)
      const slot0 = await poolContract.slot0()
      
      return {
        sqrtPriceX96: slot0.sqrtPriceX96.toString(),
        tick: slot0.tick
      }
    } catch (error) {
      console.error('Failed to read pool price from slot0:', { poolAddress, error })
      throw error // Re-throw so caller can handle appropriately
    }
  }

  /**
   * Determine if pool creation is needed
   * Pure business logic - easy to unit test
   */
  shouldCreatePool(poolInfo: PoolInfo, userWantsCreation: boolean): boolean {
    return !poolInfo.exists && userWantsCreation
  }

  /**
   * Validate pool parameters
   */
  validatePoolParams(token0: string, token1: string, tickSpacing: number): { valid: boolean; error?: string } {
    if (!token0 || !token1) {
      return { valid: false, error: 'Missing token addresses' }
    }
    
    if (token0.toLowerCase() === token1.toLowerCase()) {
      return { valid: false, error: 'Token addresses cannot be identical' }
    }
    
    if (![1, 100, 200, 2000].includes(tickSpacing)) {
      return { valid: false, error: 'Invalid tick spacing for Abstract DEX' }
    }
    
    return { valid: true }
  }
}