import { ethers } from 'ethers'
import { Token, Price } from '@uniswap/sdk-core'
import { encodeSqrtRatioX96 } from '@uniswap/v3-sdk'
import { 
  TransactionCalldata, 
  V3MintParams, 
  PoolCreationParams, 
  PoolInfo, 
  ProcessedTokens 
} from '../types/AbstractLpTypes'
import { UniverseChainId } from 'uniswap/src/features/chains/types'

/**
 * Builder for V3 transaction calldata
 * Separated concerns: pool creation vs position minting
 */
export class V3TransactionBuilder {
  
  // Abstract DEX V3 NFT Position Manager ABI
  private readonly nftManagerAbi = [
    {
      name: 'mint',
      type: 'function',
      stateMutability: 'payable',
      inputs: [
        {
          name: 'params',
          type: 'tuple',
          components: [
            { name: 'token0', type: 'address' },
            { name: 'token1', type: 'address' },
            { name: 'tickSpacing', type: 'int24' },
            { name: 'tickLower', type: 'int24' },
            { name: 'tickUpper', type: 'int24' },
            { name: 'amount0Desired', type: 'uint256' },
            { name: 'amount1Desired', type: 'uint256' },
            { name: 'amount0Min', type: 'uint256' },
            { name: 'amount1Min', type: 'uint256' },
            { name: 'recipient', type: 'address' },
            { name: 'deadline', type: 'uint256' },
            { name: 'sqrtPriceX96', type: 'uint160' }
          ]
        }
      ],
      outputs: [
        { name: 'tokenId', type: 'uint256' },
        { name: 'liquidity', type: 'uint128' },
        { name: 'amount0', type: 'uint256' },
        { name: 'amount1', type: 'uint256' }
      ]
    },
    {
      name: 'createAndInitializePoolIfNecessary',
      type: 'function',
      stateMutability: 'payable',
      inputs: [
        { name: 'token0', type: 'address' },
        { name: 'token1', type: 'address' },
        { name: 'tickSpacing', type: 'int24' },
        { name: 'sqrtPriceX96', type: 'uint160' }
      ],
      outputs: [
        { name: 'pool', type: 'address' }
      ]
    },
    {
      name: 'multicall',
      type: 'function',
      stateMutability: 'payable',
      inputs: [
        { name: 'data', type: 'bytes[]' }
      ],
      outputs: [
        { name: 'results', type: 'bytes[]' }
      ]
    }
  ] as const

  /**
   * Build complete V3 position creation transaction
   */
  async buildTransaction(params: {
    processedTokens: ProcessedTokens
    poolInfo: PoolInfo
    tickLower: number
    tickUpper: number
    recipient: string
    deadline: number
    nftManagerAddress: string
    chainId: UniverseChainId
    createPool?: boolean
    providedSqrtPriceX96?: string
  }): Promise<TransactionCalldata> {
    const {
      processedTokens,
      poolInfo,
      tickLower,
      tickUpper,
      recipient,
      deadline,
      nftManagerAddress,
      chainId,
      createPool = false,
      providedSqrtPriceX96
    } = params

    const calls: string[] = []

    // 1. Add pool creation call if needed
    const shouldCreatePool = this.shouldCreatePool(poolInfo, createPool)
    if (shouldCreatePool) {
      const sqrtPriceX96 = await this.determineSqrtPriceX96(
        poolInfo,
        processedTokens,
        chainId,
        providedSqrtPriceX96
      )

      const createPoolCall = this.buildPoolCreationCalldata({
        token0: processedTokens.finalToken0,
        token1: processedTokens.finalToken1,
        tickSpacing: poolInfo.tickSpacing,
        sqrtPriceX96
      })
      calls.push(createPoolCall)
      
    } else {
    }

    // 2. Add mint call
    const mintCall = this.buildMintCalldata({
      token0: processedTokens.finalToken0,
      token1: processedTokens.finalToken1,
      tickSpacing: poolInfo.tickSpacing,
      tickLower,
      tickUpper,
      amount0Desired: processedTokens.finalAmount0,
      amount1Desired: processedTokens.finalAmount1,
      amount0Min: processedTokens.finalAmount0Min,
      amount1Min: processedTokens.finalAmount1Min,
      recipient,
      deadline,
      sqrtPriceX96: '0' // Always 0 for mint - sqrtPriceX96 is only for pool initialization
    })
    calls.push(mintCall)

    // 3. Build final calldata
    const finalCalldata = calls.length === 1 
      ? calls[0]
      : this.buildMulticallData(calls)

    // 4. Calculate ETH value
    const value = this.calculateEthValue(processedTokens)

    return {
      to: nftManagerAddress,
      data: finalCalldata,
      value,
      from: recipient,
      chainId
    }
  }

  /**
   * Build calldata for mint function (pure function)
   */
  buildMintCalldata(params: V3MintParams): string {
    const nftInterface = new ethers.utils.Interface(this.nftManagerAbi)
    
    return nftInterface.encodeFunctionData('mint', [params])
  }

  /**
   * Build calldata for pool creation (pure function)
   */
  buildPoolCreationCalldata(params: PoolCreationParams): string {
    const nftInterface = new ethers.utils.Interface(this.nftManagerAbi)
    
    return nftInterface.encodeFunctionData('createAndInitializePoolIfNecessary', [
      params.token0,
      params.token1,
      params.tickSpacing,
      params.sqrtPriceX96
    ])
  }

  /**
   * Build multicall data (pure function)
   */
  buildMulticallData(calls: string[]): string {
    const nftInterface = new ethers.utils.Interface(this.nftManagerAbi)
    return nftInterface.encodeFunctionData('multicall', [calls])
  }

  /**
   * Determine if pool creation is needed (pure business logic)
   */
  shouldCreatePool(poolInfo: PoolInfo, userWantsCreation: boolean): boolean {
    return !poolInfo.exists && userWantsCreation
  }

  /**
   * Determine sqrtPriceX96 for new pool creation
   */
  async determineSqrtPriceX96(
    poolInfo: PoolInfo,
    processedTokens: ProcessedTokens,
    chainId: UniverseChainId,
    providedSqrtPriceX96?: string
  ): Promise<string> {
    // Use provided price if available
    if (providedSqrtPriceX96) {
      return providedSqrtPriceX96
    }

    // Calculate from token amounts ratio
    try {
      const token0Obj = new Token(chainId, processedTokens.finalToken0, 18)
      const token1Obj = new Token(chainId, processedTokens.finalToken1, 18)

      const price = new Price(
        token0Obj, 
        token1Obj, 
        processedTokens.finalAmount0, 
        processedTokens.finalAmount1
      )

      const calculatedSqrtPriceX96 = encodeSqrtRatioX96(price.numerator, price.denominator)
      const result = calculatedSqrtPriceX96.toString()


      return result
    } catch (error) {
      console.error('Failed to calculate sqrtPriceX96:', error)
      throw new Error('Cannot create new pool without valid price calculation')
    }
  }

  /**
   * Calculate ETH value to send (pure function)
   */
  calculateEthValue(processedTokens: ProcessedTokens): string {
    if (processedTokens.isToken0OriginallyETH) {
      return processedTokens.finalAmount0
    }
    if (processedTokens.isToken1OriginallyETH) {
      return processedTokens.finalAmount1
    }
    return '0'
  }
}